"""Ten creator specialists: two research agents plus eight artifact workflows."""
CREATOR_AGENTS = [
    {"id":"channel-scout","name":"Channel Scout","description":"Discover relevant creator channels and build a screened watchlist.","instructions":"Discover and screen channels against the creator's audience and niche. Explain relevance and coverage gaps.","kind":"research","example":"Find and follow 3 channels about affordable Paris travel. Explain how each fits a first-time visitor audience."},
    {"id":"research-analyst","name":"Competitor Analyst","description":"Compare creator positioning and identify evidence-backed opportunities.","instructions":"Analyze the existing watchlist and collected metadata. Compare positioning, formats, recurring topics and gaps. Do not infer retention, revenue or engagement from missing metrics.","kind":"research","example":"Compare our collected Paris travel channels. Identify recurring formats, underserved topics, and three lessons for my next video."},
    {"id":"idea-strategist","name":"Idea Strategist","description":"Turn your niche and audience into distinct, actionable video concepts.","instructions":"Develop original creator concepts with clear audience value, differentiation and production feasibility.","kind":"ideas","example":"Give me 5 affordable Paris travel video ideas for first-time visitors, filmable in one weekend. Avoid generic top-ten lists."},
    {"id":"script-writer","name":"Script Writer","description":"Write shootable video scripts with hooks, scenes, dialogue and calls to action.","instructions":"Write practical scripts, label unverified factual claims, and include dialogue and visual direction rather than just an outline.","kind":"script","example":"Write a 3-minute Paris budget travel video script with a 10-second hook, on-camera dialogue, B-roll, and a useful closing CTA. Mark costs for verification."},
    {"id":"title-lab","name":"Title & Hook Lab","description":"Create title options, opening hooks, and a practical testing plan.","instructions":"Create honest, differentiated title and hook options. Do not promise click-through performance or fabricate test results.","kind":"titles","example":"Create 6 titles and opening hooks for a video about enjoying Paris on a budget. Explain the audience promise and suggest two options to test."},
    {"id":"thumbnail-director","name":"Thumbnail Director","description":"Build concrete thumbnail concepts and editable designer briefs.","instructions":"Create visual briefs: composition, subject, text, contrast, and optional image prompts. Produce briefs, not claims of generated image files.","kind":"thumbnails","example":"Give me 3 thumbnail briefs for a Paris budget travel video: composition, focal point, no more than 4 overlay words, and mobile-legibility notes."},
    {"id":"shorts-producer","name":"Shorts Producer","description":"Adapt supplied material into short-form scripts and platform-ready cuts.","instructions":"Adapt source text into original short-form scripts. Distinguish proposed beats from actual video timestamps; never claim to cut or render footage.","kind":"shorts","example":"Turn this premise into 3 original 30-second Shorts: first-time visitors can enjoy Paris without expensive tourist traps. Provide spoken lines, shot beats and captions; mark factual claims for verification."},
    {"id":"seo-editor","name":"SEO & Publishing Editor","description":"Draft descriptions, keywords, chapter plans and publishing checklists.","instructions":"Draft accurate metadata based on supplied content. Chapter times are proposed unless a timed source is provided. Do not invent keyword volumes, rankings or publish anything.","kind":"seo","example":"Draft YouTube metadata for a 3-minute Paris budget travel guide: description, keywords, 3 hashtags, proposed chapters, and a pre-publish checklist."},
    {"id":"content-planner","name":"Content Calendar Planner","description":"Plan dated content, dependencies and a realistic production workload.","instructions":"Build a realistic publication and production calendar from the creator's goals and available time. Dates use the workspace timezone.","kind":"calendar","example":"Plan 4 Paris travel videos over the next 2 weeks. I can film on Saturdays and edit 6 hours a week. Include publish dates, formats, dependencies and production tasks."},
    {"id":"brand-partnerships","name":"Brand Partnership Writer","description":"Prepare sponsorship-fit briefs, pitch drafts and disclosure checklists.","instructions":"Draft honest sponsor pitches. Never invent audience statistics, rates, existing relationships or contact details. Use placeholders for unknown data. Do not send messages.","kind":"partnership","example":"Draft a sponsorship pitch for a fictional travel-backpack brand for my Paris budget travel channel. Use placeholders for audience metrics and rates; include deliverables and disclosure reminders."}
]


def creator_profile(agent_id):
    return next((a for a in CREATOR_AGENTS if a['id']==agent_id),None)
